data.value:
A1   Classify_1.Confidence 
       // Tool property
A2   Classify_2.Confidence
       // Tool property
A3   'MARGINAL                
       // String literal
A4   45                       
       // Numeric literal
B1   (A1 + A2) / 2             
       // Mean confidence for 2 tools
B2   Max(A1,A2)               
       // Maximum confidence of 2 tools
B3   IF(A1 > A2, "Classify_1", "Classify_2")
       // Return high-scoring tool name
B4   IF(A1 < A4, "WARN", "OK")
       // Returns 'WARN' if confidence is 
       // below 45, "OK" otherwise
B4   Exact(Classify_1.PredictedClass, A3)
       // Return TRUE if the class is 
       // 'MARGINAL', FALSE otherwise
B5   PlotString(Acquired,B4,100,100,0xFFFFFF,1)
       // Display the contents of cell B4 at 
       // 100,100 on the image

Classify_1.Confidence
  // Confidence score from Classify_1
Brightness_1.Brightness
  // Brightness value from Brightness_1

If(condition, expr1, expr2)
  // Return expr1 if condition is true, 
  // expr2 otherwise
Choose(index, expr1, expr2, expr3 ...)  
  // Return the expression specified by 
  // index
Exact(str1, str2)
  // Return TRUE if the strings match, 
  // FALSE otherwise
PlotString(image, string, X, Y, color, show)
  // Supply Acquired for image argument. 
  // String is displayed at specified 
  // location. Specify RGB color (OxFFFFFF 
  // for white). Toggle visibility with 
  // show argument.
Mean(), Mode(), Min(), Max()   
  // Statistics functions
Abs(), Exp(), Mod(), Power()   
  // Math functions
